[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>DeployCloud Blog — Discover the latest in web development</title>
  <link rel="preconnect" href="https://fonts.googleapis.com" />
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin />
  <link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&display=swap" rel="stylesheet" />
  <style>
    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

    :root {
      --bg: #FAFAFA;
      --surface: #FFFFFF;
      --border: #E5E7EB;
      --border-light: #F3F4F6;
      --text-primary: #171717;
      --text-secondary: #6B7280;
      --text-muted: #9CA3AF;
      --accent: #0072F5;
      --accent-hover: #005FCC;
      --accent-light: #EFF6FF;
      --tag-bg: #F3F4F6;
      --tag-text: #374151;
      --nav-height: 64px;
      --radius-sm: 6px;
      --radius-md: 10px;
      --radius-lg: 16px;
      --shadow-sm: 0 1px 3px rgba(0,0,0,0.06), 0 1px 2px rgba(0,0,0,0.04);
      --shadow-md: 0 4px 16px rgba(0,0,0,0.08), 0 2px 6px rgba(0,0,0,0.04);
      --shadow-lg: 0 8px 32px rgba(0,0,0,0.10), 0 4px 12px rgba(0,0,0,0.05);
      --font: 'Inter', system-ui, -apple-system, sans-serif;
    }

    body {
      font-family: var(--font);
      background: var(--bg);
      color: var(--text-primary);
      line-height: 1.6;
      -webkit-font-smoothing: antialiased;
    }

    a { color: inherit; text-decoration: none; }
    button { cursor: pointer; font-family: var(--font); }
    img { display: block; max-width: 100%; }

    .container {
      max-width: 1200px;
      margin: 0 auto;
      padding: 0 24px;
    }

    /* ─── HEADER ─────────────────────────────────────────── */
    .site-header {
      position: sticky;
      top: 0;
      z-index: 100;
      background: rgba(255,255,255,0.92);
      backdrop-filter: blur(12px);
      -webkit-backdrop-filter: blur(12px);
      border-bottom: 1px solid var(--border);
      height: var(--nav-height);
    }

    .nav-inner {
      display: flex;
      align-items: center;
      gap: 0;
      height: 100%;
    }

    .nav-logo {
      display: flex;
      align-items: center;
      gap: 8px;
      font-weight: 700;
      font-size: 17px;
      letter-spacing: -0.3px;
      color: var(--text-primary);
      margin-right: 32px;
      flex-shrink: 0;
    }

    .logo-mark {
      width: 28px;
      height: 28px;
      background: var(--accent);
      border-radius: 6px;
      display: flex;
      align-items: center;
      justify-content: center;
    }

    .logo-mark svg { color: white; }

    .nav-links {
      display: flex;
      align-items: center;
      gap: 2px;
      flex: 1;
    }

    .nav-item {
      position: relative;
    }

    .nav-btn {
      display: flex;
      align-items: center;
      gap: 4px;
      padding: 6px 12px;
      background: none;
      border: none;
      font-size: 14px;
      font-weight: 500;
      color: var(--text-secondary);
      border-radius: var(--radius-sm);
      transition: color 150ms, background 150ms;
      white-space: nowrap;
    }

    .nav-btn:hover, .nav-btn.active {
      color: var(--text-primary);
      background: var(--tag-bg);
    }

    .nav-btn svg { flex-shrink: 0; transition: transform 200ms; }
    .nav-item:hover .nav-btn svg,
    .nav-btn.open svg { transform: rotate(180deg); }

    .nav-actions {
      display: flex;
      align-items: center;
      gap: 8px;
      margin-left: auto;
    }

    .btn-ghost {
      padding: 6px 14px;
      background: none;
      border: none;
      font-size: 14px;
      font-weight: 500;
      color: var(--text-secondary);
      border-radius: var(--radius-sm);
      transition: color 150ms, background 150ms;
    }
    .btn-ghost:hover { color: var(--text-primary); background: var(--tag-bg); }

    .btn-primary {
      padding: 7px 16px;
      background: var(--text-primary);
      color: white;
      border: none;
      font-size: 14px;
      font-weight: 600;
      border-radius: var(--radius-sm);
      transition: background 150ms, transform 100ms;
    }
    .btn-primary:hover { background: #333; }
    .btn-primary:active { transform: scale(0.98); }

    /* Mega Menu */
    .mega-menu {
      display: none;
      position: absolute;
      top: calc(100% + 8px);
      left: 0;
      min-width: 640px;
      background: white;
      border: 1px solid var(--border);
      border-radius: var(--radius-md);
      box-shadow: var(--shadow-lg);
      padding: 20px;
      z-index: 200;
    }

    .nav-item:hover .mega-menu,
    .mega-menu:hover { display: flex; gap: 32px; }

    .mega-col { flex: 1; }

    .mega-col-title {
      font-size: 11px;
      font-weight: 700;
      letter-spacing: 0.08em;
      text-transform: uppercase;
      color: var(--text-muted);
      margin-bottom: 12px;
    }

    .mega-link {
      display: flex;
      flex-direction: column;
      padding: 8px 10px;
      border-radius: var(--radius-sm);
      transition: background 150ms;
      margin-bottom: 2px;
    }
    .mega-link:hover { background: var(--bg); }
    .mega-link-title { font-size: 13px; font-weight: 600; color: var(--text-primary); }
    .mega-link-desc { font-size: 12px; color: var(--text-muted); margin-top: 1px; }

    /* Resources dropdown (smaller) */
    .resources-menu {
      display: none;
      position: absolute;
      top: calc(100% + 8px);
      left: 0;
      min-width: 520px;
      background: white;
      border: 1px solid var(--border);
      border-radius: var(--radius-md);
      box-shadow: var(--shadow-lg);
      padding: 20px;
      z-index: 200;
    }
    .nav-item:hover .resources-menu,
    .resources-menu:hover { display: flex; gap: 24px; }

    /* ─── HERO BAND ──────────────────────────────────────── */
    .hero-band {
      background: white;
      border-bottom: 1px solid var(--border);
      padding: 40px 0 32px;
    }

    .hero-band h1 {
      font-size: clamp(26px, 4vw, 38px);
      font-weight: 800;
      letter-spacing: -0.03em;
      color: var(--text-primary);
      line-height: 1.15;
    }

    .hero-band p {
      margin-top: 8px;
      font-size: 16px;
      color: var(--text-secondary);
      max-width: 520px;
    }

    /* ─── FILTERS ────────────────────────────────────────── */
    .filters-bar {
      background: white;
      border-bottom: 1px solid var(--border);
      padding: 16px 0;
      position: sticky;
      top: var(--nav-height);
      z-index: 90;
    }

    .filters-inner {
      display: flex;
      align-items: center;
      gap: 8px;
      flex-wrap: nowrap;
      overflow-x: auto;
      scrollbar-width: none;
    }
    .filters-inner::-webkit-scrollbar { display: none; }

    .filter-pill {
      display: inline-flex;
      align-items: center;
      padding: 6px 14px;
      border-radius: 999px;
      border: 1px solid var(--border);
      background: white;
      font-size: 13px;
      font-weight: 500;
      color: var(--text-secondary);
      white-space: nowrap;
      transition: all 150ms;
      flex-shrink: 0;
    }
    .filter-pill:hover {
      border-color: var(--accent);
      color: var(--accent);
      background: var(--accent-light);
    }
    .filter-pill.active {
      background: var(--accent);
      border-color: var(--accent);
      color: white;
    }

    .search-wrap {
      margin-left: auto;
      flex-shrink: 0;
      position: relative;
    }

    .search-input {
      padding: 7px 12px 7px 36px;
      border: 1px solid var(--border);
      border-radius: 999px;
      font-size: 13px;
      font-family: var(--font);
      color: var(--text-primary);
      background: var(--bg);
      width: 200px;
      transition: border-color 150ms, box-shadow 150ms, width 200ms;
      outline: none;
    }
    .search-input:focus {
      border-color: var(--accent);
      box-shadow: 0 0 0 3px rgba(0,114,245,0.12);
      width: 260px;
    }
    .search-input::placeholder { color: var(--text-muted); }

    .search-icon {
      position: absolute;
      left: 12px;
      top: 50%;
      transform: translateY(-50%);
      color: var(--text-muted);
      pointer-events: none;
    }

    /* ─── MAIN CONTENT ───────────────────────────────────── */
    .main-content { padding: 48px 0 64px; }

    /* ─── FEATURED SECTION ───────────────────────────────── */
    .section-label {
      font-size: 11px;
      font-weight: 700;
      letter-spacing: 0.1em;
      text-transform: uppercase;
      color: var(--text-muted);
      margin-bottom: 20px;
    }

    .featured-grid {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 20px;
      margin-bottom: 24px;
    }

    .featured-card {
      background: white;
      border: 1px solid var(--border);
      border-radius: var(--radius-lg);
      overflow: hidden;
      display: flex;
      flex-direction: column;
      transition: box-shadow 200ms, transform 200ms;
    }
    .featured-card:hover {
      box-shadow: var(--shadow-md);
      transform: translateY(-2px);
    }

    .featured-img {
      width: 100%;
      aspect-ratio: 16/9;
      object-fit: cover;
      background: linear-gradient(135deg, #0072F5 0%, #00D4FF 100%);
    }

    .featured-img-placeholder {
      width: 100%;
      aspect-ratio: 16/9;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 32px;
      font-weight: 800;
      color: rgba(255,255,255,0.9);
      letter-spacing: -1px;
    }

    .featured-img-1 { background: linear-gradient(135deg, #0072F5 0%, #00D4FF 100%); }
    .featured-img-2 { background: linear-gradient(135deg, #171717 0%, #444 100%); }
    .featured-img-3 { background: linear-gradient(135deg, #6366F1 0%, #8B5CF6 100%); }

    .featured-body {
      padding: 20px;
      flex: 1;
      display: flex;
      flex-direction: column;
    }

    .card-meta {
      display: flex;
      align-items: center;
      gap: 8px;
      font-size: 12px;
      color: var(--text-muted);
      margin-bottom: 10px;
    }

    .card-meta-dot { width: 3px; height: 3px; border-radius: 50%; background: var(--border); }

    .card-title {
      font-size: 16px;
      font-weight: 700;
      letter-spacing: -0.02em;
      line-height: 1.3;
      color: var(--text-primary);
      margin-bottom: 10px;
    }

    .featured-card .card-title { font-size: 17px; }

    .card-excerpt {
      font-size: 13px;
      color: var(--text-secondary);
      line-height: 1.65;
      flex: 1;
      display: -webkit-box;
      -webkit-line-clamp: 3;
      -webkit-box-orient: vertical;
      overflow: hidden;
    }

    .card-author {
      display: flex;
      align-items: center;
      gap: 8px;
      margin-top: 14px;
    }

    .avatar {
      width: 26px;
      height: 26px;
      border-radius: 50%;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 11px;
      font-weight: 700;
      color: white;
      flex-shrink: 0;
    }

    .avatar-sm {
      width: 22px;
      height: 22px;
      font-size: 10px;
    }

    .author-name {
      font-size: 12px;
      font-weight: 600;
      color: var(--text-secondary);
    }

    /* ─── STATS STRIP ────────────────────────────────────── */
    .stats-strip {
      background: var(--text-primary);
      border-radius: var(--radius-md);
      padding: 20px 28px;
      display: flex;
      align-items: center;
      gap: 0;
      margin-bottom: 48px;
      overflow: hidden;
    }

    .stat-item {
      flex: 1;
      display: flex;
      flex-direction: column;
      align-items: center;
      text-align: center;
      padding: 0 16px;
      position: relative;
    }

    .stat-item + .stat-item::before {
      content: '';
      position: absolute;
      left: 0;
      top: 10%;
      height: 80%;
      width: 1px;
      background: rgba(255,255,255,0.15);
    }

    .stat-number {
      font-size: clamp(22px, 3vw, 30px);
      font-weight: 800;
      color: white;
      letter-spacing: -0.04em;
      line-height: 1;
    }

    .stat-number span { color: var(--accent); }

    .stat-label {
      font-size: 12px;
      color: rgba(255,255,255,0.55);
      margin-top: 5px;
      line-height: 1.4;
      max-width: 180px;
    }

    /* ─── LATEST NEWS ────────────────────────────────────── */
    .section-header {
      display: flex;
      align-items: baseline;
      justify-content: space-between;
      margin-bottom: 20px;
    }

    .section-title {
      font-size: 20px;
      font-weight: 700;
      letter-spacing: -0.02em;
    }

    .posts-grid {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 20px;
    }

    .post-card {
      background: white;
      border: 1px solid var(--border);
      border-radius: var(--radius-md);
      padding: 20px;
      display: flex;
      flex-direction: column;
      transition: box-shadow 200ms, transform 200ms;
    }
    .post-card:hover {
      box-shadow: var(--shadow-md);
      transform: translateY(-2px);
    }

    .post-card.hidden { display: none; }

    .category-tag {
      display: inline-flex;
      align-items: center;
      padding: 3px 9px;
      border-radius: 999px;
      background: var(--tag-bg);
      font-size: 11px;
      font-weight: 600;
      color: var(--tag-text);
      letter-spacing: 0.01em;
      margin-bottom: 10px;
      width: fit-content;
    }

    .category-tag.engineering { background: #ECFDF5; color: #065F46; }
    .category-tag.customers { background: #FFF7ED; color: #9A3412; }
    .category-tag.security { background: #FFF1F2; color: #9F1239; }
    .category-tag.v0 { background: #F5F3FF; color: #5B21B6; }
    .category-tag.company-news { background: #EFF6FF; color: #1D4ED8; }
    .category-tag.press { background: #FAFAF9; color: #44403C; }
    .category-tag.changelog { background: #FDF4FF; color: #7E22CE; }
    .category-tag.community { background: #ECFEFF; color: #155E75; }

    .no-results {
      display: none;
      grid-column: 1 / -1;
      text-align: center;
      padding: 64px 0;
      color: var(--text-muted);
    }
    .no-results.visible { display: flex; flex-direction: column; align-items: center; gap: 8px; }
    .no-results-icon { font-size: 40px; margin-bottom: 8px; }
    .no-results h3 { font-size: 16px; font-weight: 600; color: var(--text-secondary); }
    .no-results p { font-size: 14px; }

    /* ─── SHOW MORE ──────────────────────────────────────── */
    .show-more-wrap {
      display: flex;
      justify-content: center;
      margin-top: 32px;
    }

    .btn-show-more {
      padding: 10px 24px;
      background: white;
      border: 1px solid var(--border);
      border-radius: var(--radius-sm);
      font-size: 14px;
      font-weight: 600;
      color: var(--text-primary);
      display: flex;
      align-items: center;
      gap: 6px;
      transition: all 150ms;
    }
    .btn-show-more:hover {
      border-color: var(--accent);
      color: var(--accent);
      box-shadow: var(--shadow-sm);
    }
    .btn-show-more:active { transform: scale(0.98); }

    /* ─── CTA BANNER ─────────────────────────────────────── */
    .cta-section {
      background: white;
      border-top: 1px solid var(--border);
      padding: 64px 0;
    }

    .cta-inner {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 40px;
      align-items: center;
    }

    .cta-main h2 {
      font-size: clamp(22px, 3vw, 32px);
      font-weight: 800;
      letter-spacing: -0.03em;
      line-height: 1.2;
      margin-bottom: 16px;
    }

    .cta-main h2 strong {
      color: var(--accent);
      font-weight: 800;
    }

    .cta-main p {
      font-size: 15px;
      color: var(--text-secondary);
      margin-bottom: 24px;
    }

    .cta-btns {
      display: flex;
      gap: 10px;
      flex-wrap: wrap;
    }

    .btn-accent {
      padding: 10px 20px;
      background: var(--accent);
      color: white;
      border: none;
      border-radius: var(--radius-sm);
      font-size: 14px;
      font-weight: 600;
      transition: background 150ms, transform 100ms;
    }
    .btn-accent:hover { background: var(--accent-hover); }
    .btn-accent:active { transform: scale(0.98); }

    .btn-outline {
      padding: 10px 20px;
      background: white;
      color: var(--text-primary);
      border: 1px solid var(--border);
      border-radius: var(--radius-sm);
      font-size: 14px;
      font-weight: 600;
      transition: all 150ms;
    }
    .btn-outline:hover { border-color: var(--text-primary); box-shadow: var(--shadow-sm); }

    .enterprise-block {
      background: var(--bg);
      border: 1px solid var(--border);
      border-radius: var(--radius-lg);
      padding: 28px 32px;
    }

    .enterprise-block .badge {
      display: inline-flex;
      align-items: center;
      gap: 6px;
      padding: 4px 10px;
      background: var(--text-primary);
      color: white;
      border-radius: 999px;
      font-size: 11px;
      font-weight: 700;
      letter-spacing: 0.05em;
      text-transform: uppercase;
      margin-bottom: 14px;
    }

    .enterprise-block h3 {
      font-size: 18px;
      font-weight: 700;
      letter-spacing: -0.02em;
      margin-bottom: 8px;
    }

    .enterprise-block p {
      font-size: 13px;
      color: var(--text-secondary);
      margin-bottom: 16px;
      line-height: 1.6;
    }

    /* ─── FOOTER ─────────────────────────────────────────── */
    .site-footer {
      background: var(--text-primary);
      color: rgba(255,255,255,0.55);
      padding: 48px 0 32px;
    }

    .footer-top {
      display: grid;
      grid-template-columns: repeat(5, 1fr);
      gap: 24px 16px;
      margin-bottom: 40px;
    }

    .footer-group-title {
      font-size: 11px;
      font-weight: 700;
      letter-spacing: 0.08em;
      text-transform: uppercase;
      color: rgba(255,255,255,0.9);
      margin-bottom: 12px;
    }

    .footer-links { list-style: none; display: flex; flex-direction: column; gap: 7px; }

    .footer-links a {
      font-size: 13px;
      color: rgba(255,255,255,0.5);
      transition: color 150ms;
    }
    .footer-links a:hover { color: rgba(255,255,255,0.9); }

    .footer-bottom {
      border-top: 1px solid rgba(255,255,255,0.1);
      padding-top: 24px;
      display: flex;
      align-items: center;
      justify-content: space-between;
      flex-wrap: wrap;
      gap: 12px;
    }

    .footer-logo {
      display: flex;
      align-items: center;
      gap: 8px;
      font-weight: 700;
      font-size: 15px;
      color: white;
    }

    .footer-logo-mark {
      width: 24px;
      height: 24px;
      background: var(--accent);
      border-radius: 5px;
      display: flex;
      align-items: center;
      justify-content: center;
    }

    .status-pill {
      display: flex;
      align-items: center;
      gap: 6px;
      font-size: 12px;
      color: rgba(255,255,255,0.5);
    }

    .status-dot {
      width: 7px;
      height: 7px;
      border-radius: 50%;
      background: #10B981;
      box-shadow: 0 0 6px rgba(16,185,129,0.5);
    }

    .footer-copy { font-size: 12px; color: rgba(255,255,255,0.35); }

    /* ─── RESPONSIVE ─────────────────────────────────────── */
    @media (max-width: 1024px) {
      .footer-top { grid-template-columns: repeat(3, 1fr); }
      .mega-menu { min-width: 540px; }
    }

    @media (max-width: 768px) {
      .featured-grid { grid-template-columns: 1fr; }
      .posts-grid { grid-template-columns: repeat(2, 1fr); }
      .stats-strip { flex-direction: column; gap: 20px; }
      .stat-item + .stat-item::before { display: none; }
      .cta-inner { grid-template-columns: 1fr; }
      .footer-top { grid-template-columns: repeat(2, 1fr); }
      .nav-links { display: none; }
      .hero-band { padding: 28px 0 24px; }
    }

    @media (max-width: 480px) {
      .posts-grid { grid-template-columns: 1fr; }
      .footer-top { grid-template-columns: 1fr 1fr; }
      .container { padding: 0 16px; }
    }

    /* ─── UTILITY ────────────────────────────────────────── */
    .divider { height: 1px; background: var(--border); margin: 40px 0; }
    .visually-hidden { display: none !important; }

    /* Avatar color palette */
    .av-blue { background: #0072F5; }
    .av-indigo { background: #6366F1; }
    .av-emerald { background: #10B981; }
    .av-amber { background: #F59E0B; }
    .av-rose { background: #F43F5E; }
    .av-violet { background: #8B5CF6; }
    .av-teal { background: #14B8A6; }
    .av-orange { background: #F97316; }
  </style>
</head>
