<script>
(function() {
  'use strict';

  /* ── State ──────────────────────────────────────── */
  let activeCategory = 'all';
  let searchQuery = '';
  let moreLoaded = false;

  /* ── Elements ───────────────────────────────────── */
  const filterPills = document.querySelectorAll('.filter-pill');
  const searchInput = document.querySelector('.search-input');
  const postsGrid = document.getElementById('posts-grid');
  const featuredGrid = document.getElementById('featured-grid');
  const noResults = document.getElementById('no-results');
  const showMoreBtn = document.getElementById('show-more-btn');
  const showMoreWrap = document.getElementById('show-more-wrap');
  const featuredSection = document.querySelector('.featured-section');

  /* ── Category Filter ────────────────────────────── */
  filterPills.forEach(pill => {
    pill.addEventListener('click', () => {
      filterPills.forEach(p => {
        p.classList.remove('active');
        p.setAttribute('aria-pressed', 'false');
      });
      pill.classList.add('active');
      pill.setAttribute('aria-pressed', 'true');
      activeCategory = pill.dataset.category;
      applyFilters();
    });
  });

  /* ── Search ─────────────────────────────────────── */
  let debounceTimer;
  searchInput.addEventListener('input', () => {
    clearTimeout(debounceTimer);
    debounceTimer = setTimeout(() => {
      searchQuery = searchInput.value.trim().toLowerCase();
      applyFilters();
    }, 180);
  });

  /* ── Filter Logic ───────────────────────────────── */
  function applyFilters() {
    const allCards = postsGrid.querySelectorAll('.post-card');
    let visibleCount = 0;

    // Show/hide featured section based on filters
    const showFeatured = activeCategory === 'all' && searchQuery === '';
    featuredSection.style.display = showFeatured ? '' : 'none';

    allCards.forEach(card => {
      const catMatch = activeCategory === 'all' || card.dataset.category === activeCategory;
      const searchText = card.dataset.searchable || '';
      const titleText = (card.dataset.title || '').toLowerCase();
      const searchMatch = searchQuery === '' ||
        searchText.includes(searchQuery) ||
        titleText.includes(searchQuery);

      const shouldShow = catMatch && searchMatch;
      // Respect "loaded more" state for hidden posts
      const isExtended = card.classList.contains('hidden') && !moreLoaded;

      if (shouldShow && !isExtended) {
        card.style.display = '';
        visibleCount++;
      } else if (shouldShow && isExtended) {
        card.style.display = '';
        visibleCount++;
      } else {
        card.style.display = 'none';
      }
    });

    // No results
    if (visibleCount === 0) {
      noResults.classList.add('visible');
    } else {
      noResults.classList.remove('visible');
    }

    // Show more button visibility
    const hasHidden = Array.from(allCards).some(c => c.classList.contains('hidden') && c.style.display !== 'none');
    showMoreWrap.style.display = (activeCategory === 'all' && searchQuery === '' && !moreLoaded) ? '' : 'none';
  }

  /* ── Show More ──────────────────────────────────── */
  showMoreBtn.addEventListener('click', () => {
    moreLoaded = true;
    const hiddenCards = postsGrid.querySelectorAll('.post-card.hidden');
    hiddenCards.forEach((card, i) => {
      card.classList.remove('hidden');
      // Animate in
      card.style.opacity = '0';
      card.style.transform = 'translateY(16px)';
      card.style.transition = 'opacity 300ms ease-out, transform 300ms ease-out';
      setTimeout(() => {
        card.style.opacity = '1';
        card.style.transform = 'translateY(0)';
      }, i * 80);
    });
    showMoreWrap.style.display = 'none';
  });

  /* ── Nav Dropdown keyboard support ─────────────── */
  document.querySelectorAll('.nav-btn').forEach(btn => {
    btn.addEventListener('click', function() {
      const isOpen = this.classList.contains('open');
      document.querySelectorAll('.nav-btn').forEach(b => b.classList.remove('open'));
      if (!isOpen) this.classList.add('open');
    });
  });

  // Close dropdowns on outside click
  document.addEventListener('click', (e) => {
    if (!e.target.closest('.nav-item')) {
      document.querySelectorAll('.nav-btn').forEach(b => b.classList.remove('open'));
    }
  });

  /* ── Initial state ──────────────────────────────── */
  applyFilters();

})();
</script>

